import { lazy, Suspense } from 'react';

const Slow = lazy(async () => ({ default: () => <p>slow-data</p> }));

export function Page() {
  return (
    <>
      <header>fast</header>
      <Suspense fallback={<p>loading slow</p>}>
        <Slow />
      </Suspense>
      <footer>fast</footer>
    </>
  );
}
